.card.result .share-buttons button{font-size:14px;padding:9px;min-height:44px;}
.card.result .share-buttons #save-result{grid-column:1/-1;grid-row:1;background:#dff18d;}
.card.result .share-buttons #copy-result{grid-column:auto;}
.card.result #share-result{background:#e4e9df;}
.card.result #share-status{font-size:12px;min-height:0;margin:6px 0;}
.card.result #share-status:empty{display:none;}
.card.result .music-credits{margin:7px 0;font-size:10px;}
.card.result #start{min-height:44px;padding:9px;margin-top:4px;font-size:15px;}
@media(max-width:430px){.card.result h2{font-size:22px;}}
@media(max-height:430px) and (orientation:landscape){
 .card.result{width:min(760px,calc(var(--visible-width,100vw) - 32px - var(--safe-left,0px) - var(--safe-right,0px)));display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 16px;align-items:start;}
 .card.result #result-brand{grid-column:1;grid-row:1;}
 .card.result #result-score-block{grid-column:1;grid-row:2;}
 .card.result h2{grid-column:1;grid-row:3;font-size:22px;}
 .card.result #card-subtitle{grid-column:1;grid-row:4;}
 .card.result #landing-preview{grid-column:2;grid-row:1/5;align-self:center;}
 .card.result #card-text{grid-column:2;grid-row:5;}
 .card.result #share-actions{grid-column:1/-1;grid-row:6;}
 .card.result .share-buttons{grid-template-columns:1fr 1fr 1fr;}
 .card.result .share-buttons #save-result{grid-column:1;grid-row:1;}
 .card.result .share-buttons #share-result{grid-column:2;grid-row:1;}
 .card.result .share-buttons #copy-result{grid-column:3;grid-row:1;}
 .card.result .music-credits{grid-column:1;grid-row:7;align-self:center;}
 .card.result #start{grid-column:2;grid-row:7;}
}

/* Protect live play, including canvas, HUD text, label descendants and gaps.
   Ordinary UI buttons keep native touch/click/focus; the scrolling dialog,
   credit links and manual-copy #share-status text retain browser behavior. */
[data-play-surface]{touch-action:none}
[data-play-surface],[data-play-surface] *,header h1,#sound-status,header button,header button *,.card button,.card button *{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
[data-play-surface] canvas,[data-play-surface] img{-webkit-user-drag:none}
[data-play-surface] [data-limb] *{pointer-events:none}

/* Standalone portrait: the real field continues behind controls to the bottom.
   HUD stays in the original play area; only the renderer's lower view expands. */
html[data-controls-raised="true"] .arena{grid-row:1/3;margin-bottom:calc(-1 * var(--controls-lift,0px))}
html[data-controls-raised="true"] .limbs{position:relative;z-index:1}
html[data-controls-raised="true"] #air-guide{bottom:calc(28px + var(--scene-extension,0px))}

/* Installed web app: ordinary DOM modal, never the iOS native dialog top layer. */
.dialog-backdrop{position:fixed;inset:0;z-index:99;background:#153c4559;touch-action:none}
.card.fallback[open]{z-index:100}
.card.fallback:not([open]){display:none}

